python -c "import pandas as pd, numpy as np; from pymatgen.core import Structure; from pymatgen.analysis.molecule_structure_comparator import CovalentRadius; df=pd.read_csv('nlo_pool.csv'); skip=set(range(1,5))|set(range(8,20))|set(range(31,37))|set(range(94,100)); print('Cation first coordination shell: coordination count, mean bond length, bond-orientation eigenvalue spread');
for r in df.itertuples():
 if int(r.candidate_id[1:]) in skip: continue
 s=Structure.from_str(r.poscar,fmt='poscar'); out=[]
 for el in s.composition.elements:
  if el.symbol in ['O','S','Se','Te','P','As','N','Cl','Br','I','C']: continue
  ns=[]; lens=[]; vs=[]
  for i,site in enumerate(s):
   if site.specie != el: continue
   near=[n for n in s.get_neighbors(site,4.5) if n.specie.X>el.X+.25]; near.sort(key=lambda x:x.nn_distance)
   if not near: continue
   rad=near[0].nn_distance*1.22; shell=[n for n in near if n.nn_distance<rad]; ns.append(len(shell))
   for n in shell:
    lens.append(n.nn_distance); vs.append((n.coords-site.coords)/n.nn_distance)
  if vs:
   v=np.array(vs); e=np.linalg.eigvalsh(v.T@v/len(v)); out.append(f'{el}:{min(ns)}-{max(ns)} {np.mean(lens):.2f}A A={np.ptp(e):.3f}')
 print(r.candidate_id,s.composition.reduced_formula,'; '.join(out))"

